node -e "
(async () => {
  const fs = require('fs');
  const mod = await import('./node_modules/@re-cinq/eslint-plugin-re-lint/dist/vendor/spec/spec-status-coverage.js');
  const { statementCoverage, coverageTier, expectedStatus } = mod;

  const specContent = fs.readFileSync('./specs/hal-engine-architecture/spec.md', 'utf8');
  const coverage = statementCoverage(specContent);
  const tier = coverageTier(coverage.testable, coverage.linked);
  const expected = expectedStatus(tier);
  console.log('Architecture spec coverage:', coverage.testable, 'testable,', coverage.linked, 'linked');
  console.log('Expected status:', expected);

  // Check current status
  const statusLine = specContent.split('\n').find(l => l.includes('Status'));
  console.log('Current status line:', statusLine);
})();
" 2>&1

